section class="comm-card"><h4>Achievements</h4><div class="admin-table-wrap"><table><tr><th>Achievement</th><th>Progress</th><th>Status</th><th>Description</th></tr>';if($ach)while($a=$ach->fetch_assoc())echo '<tr><td>'.htmlspecialchars($a['name'],ENT_QUOTES,'UTF-8').'</td><td>'.number_format((int)$a['progress_value']).' / '.number_format((int)$a['target_value']).'</td><td>'.($a['unlocked_at']?'Unlocked':'In progress').'</td><td>'.htmlspecialchars($a['description'],ENT_QUOTES,'UTF-8').'</td></tr>';echo '</table></div></section></div>'; $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
